-- ============================================
-- LUMA — Oz Tome 4 : Chapitres XIII-XVII (Le sauvetage aux Singes Ailés, jusqu'au départ du ballon)
-- Texte original, domaine public
-- ============================================


with s as (select id from books where title = 'The Wonderful Wizard of Oz' and is_series = true),
     lang as (select id from languages where code = 'en')
insert into books (language_id, title, theme, description, cecr_level, cover_emoji, total_pages, position, series_id, volume_number)
select lang.id, 'Tome 4 : Le grand imposteur', 'Classique • L. Frank Baum (1900)', 'Les amis retrouvent leurs compagnons blessés, s''envolent grâce aux Singes Ailés, découvrent qu''Oz n''est qu''un homme ordinaire déguisé, et assistent au départ précipité de son ballon.', 'B1', '🎈', 5, 1, s.id, 4
from lang, s;


with b as (select id from books where title = 'Tome 4 : Le grand imposteur' and series_id = (select id from books where title = 'The Wonderful Wizard of Oz' and is_series = true))
insert into book_pages (book_id, page_number, sentences)
select b.id, 1, '[{"en": "The Cowardly Lion was pleased to hear the Wicked Witch had been melted, and Dorothy set him free. Her first act was to call all the Winkies together and tell them they were no longer slaves.", "fr": "Le Lion Peureux fut ravi d''apprendre que la Méchante Sorcière avait fondu, et Dorothy le libéra. Son premier acte fut de rassembler tous les Winkies et de leur dire qu''ils n''étaient plus esclaves."}, {"en": "''If our friends, the Scarecrow and the Tin Woodman, were only with us,'' said the Lion, ''I should be quite happy.'' ''We must try to find them,'' said the girl.", "fr": "''Si seulement nos amis, l''Épouvantail et l''Homme de Fer-Blanc, étaient avec nous,'' dit le Lion, ''je serais tout à fait heureux.'' ''Nous devons essayer de les retrouver,'' dit la fillette."}, {"en": "The Winkies found the Tin Woodman all battered and bent on the rocky plain. Skilled tinsmiths worked for three days and four nights, hammering and soldering him, until he was straightened into his old form.", "fr": "Les Winkies trouvèrent l''Homme de Fer-Blanc tout cabossé et tordu sur la plaine rocheuse. Des ferblantiers habiles travaillèrent trois jours et quatre nuits, martelant et soudant, jusqu''à ce qu''il retrouve sa forme d''antan."}, {"en": "When he walked into Dorothy''s room and thanked her, he was so pleased that he wept tears of joy, and Dorothy had to wipe every tear carefully so his joints would not rust.", "fr": "Quand il entra dans la chambre de Dorothy et la remercia, il fut si content qu''il versa des larmes de joie, et Dorothy dut essuyer chaque larme soigneusement pour que ses articulations ne rouillent pas."}, {"en": "They found the tree where the Winged Monkeys had tossed the Scarecrow''s clothes. The Tin Woodman chopped it down with his new golden axe-handle, and the Scarecrow was stuffed with fresh straw, as good as ever.", "fr": "Ils trouvèrent l''arbre où les Singes Ailés avaient jeté les habits de l''Épouvantail. L''Homme de Fer-Blanc l''abattit avec son nouveau manche de hache en or, et l''Épouvantail fut rembourré de paille fraîche, comme neuf."}, {"en": "''We must go back to Oz, and claim his promise,'' said Dorothy. The Winkies gave them golden collars, a diamond bracelet, and a walking stick as farewell gifts, and Dorothy found the Golden Cap in the Witch''s cupboard and decided to wear it.", "fr": "''Nous devons retourner voir Oz, et réclamer sa promesse,'' dit Dorothy. Les Winkies leur offrirent des colliers dorés, un bracelet de diamants, et une canne comme cadeaux d''adieu, et Dorothy trouva le Bonnet d''Or dans le placard de la Sorcière et décida de le porter."}]'::jsonb from b;


with b as (select id from books where title = 'Tome 4 : Le grand imposteur' and series_id = (select id from books where title = 'The Wonderful Wizard of Oz' and is_series = true))
insert into book_pages (book_id, page_number, sentences)
select b.id, 2, '[{"en": "Lost in the great fields on their way back, the friends began to lose hope. ''Suppose we call the field mice,'' Dorothy suggested. ''They could probably tell us the way to the Emerald City.''", "fr": "Perdus dans les grands champs sur le chemin du retour, les amis commencèrent à perdre espoir. ''Et si on appelait les souris des champs,'' suggéra Dorothy. ''Elles pourraient sûrement nous indiquer le chemin de la Cité d''Émeraude.''"}, {"en": "The Queen of the Mice noticed Dorothy''s Golden Cap. ''Why don''t you use the charm of the Cap, and call the Winged Monkeys to you? They will carry you to the City of Oz in less than an hour.''", "fr": "La Reine des Souris remarqua le Bonnet d''Or de Dorothy. ''Pourquoi n''utilisez-vous pas le charme du Bonnet, et n''appelez-vous pas les Singes Ailés ? Ils vous porteront à la Cité d''Oz en moins d''une heure.''"}, {"en": "Dorothy read the charm and said the magic words, standing first on her left foot, then her right, then both. At once the Winged Monkeys flew up to them, chattering and flapping their wings.", "fr": "Dorothy lut le charme et dit les mots magiques, se tenant d''abord sur son pied gauche, puis sur son droit, puis sur les deux. Aussitôt les Singes Ailés volèrent vers eux, jacassant et battant des ailes."}, {"en": "The King of the Monkeys bowed low before Dorothy and carried her gently through the air, along with all her friends. During the flight, he told her the long story of how his grandfather had once mocked a young man named Quelala, angering the sorceress Gayelette, who bound the Winged Monkeys to obey the owner of the Golden Cap three times.", "fr": "Le Roi des Singes s''inclina bien bas devant Dorothy et la porta doucement à travers les airs, avec tous ses amis. Pendant le vol, il lui raconta la longue histoire de comment son grand-père avait autrefois raillé un jeune homme nommé Quelala, mettant en colère la sorcière Gayelette, qui lia les Singes Ailés à obéir trois fois au propriétaire du Bonnet d''Or."}, {"en": "''Now the Golden Cap is yours, and three times you have the right to lay your wishes upon us,'' said the King. They set the travelers down safely before the gate of the Emerald City, bowed, and flew away.", "fr": "''Maintenant le Bonnet d''Or est à vous, et trois fois vous avez le droit de nous exprimer vos souhaits,'' dit le Roi. Ils déposèrent les voyageurs en sécurité devant la porte de la Cité d''Émeraude, s''inclinèrent, et s''envolèrent."}, {"en": "The Guardian of the Gates was astonished they had returned, and even more astonished to learn Dorothy had melted the Witch. They demanded their promised gifts, and threatened to call the Winged Monkeys if Oz refused to see them.", "fr": "Le Gardien des Portes fut stupéfait qu''ils soient revenus, et encore plus stupéfait d''apprendre que Dorothy avait fait fondre la Sorcière. Ils réclamèrent leurs cadeaux promis, et menacèrent d''appeler les Singes Ailés si Oz refusait de les recevoir."}]'::jsonb from b;


with b as (select id from books where title = 'Tome 4 : Le grand imposteur' and series_id = (select id from books where title = 'The Wonderful Wizard of Oz' and is_series = true))
insert into book_pages (book_id, page_number, sentences)
select b.id, 3, '[{"en": "In the Throne Room, a solemn Voice spoke from nowhere. The Lion gave such a loud roar that Toto jumped and tipped over a screen in the corner, revealing a little old bald man who seemed as surprised as they were.", "fr": "Dans la Salle du Trône, une Voix solennelle parla de nulle part. Le Lion poussa un rugissement si fort que Toto sursauta et renversa un paravent dans le coin, révélant un petit vieil homme chauve qui semblait aussi surpris qu''eux."}, {"en": "''I am Oz, the Great and Terrible,'' said the little man, in a trembling voice. ''But don''t strike me—please don''t—and I''ll do anything you want me to.'' ''I thought Oz was a great Head,'' said Dorothy.", "fr": "''Je suis Oz, le Grand et le Terrible,'' dit le petit homme, d''une voix tremblante. ''Mais ne me frappez pas—s''il vous plaît pas—et je ferai tout ce que vous voudrez.'' ''Je pensais qu''Oz était une grande Tête,'' dit Dorothy."}, {"en": "''You''re more than that,'' said the Scarecrow, in a grieved tone; ''you''re a humbug.'' ''Exactly so!'' declared the little man. ''I am a humbug.'' He explained he was really a balloonist from Omaha who had drifted into this land by accident.", "fr": "''Vous êtes plus que ça,'' dit l''Épouvantail, d''un ton peiné ; ''vous êtes un imposteur.'' ''Exactement !'' déclara le petit homme. ''Je suis un imposteur.'' Il expliqua qu''il était en fait un aéronaute d''Omaha qui avait dérivé dans ce pays par accident."}, {"en": "He revealed the great Head was made of paper on a wire, his Lady disguise was a dress and mask, his Beast was sewn skins, and his Ball of Fire was cotton hung from the ceiling. ''I have fooled everyone so long that I thought I should never be found out.''", "fr": "Il révéla que la grande Tête était faite de papier sur un fil, son déguisement de Dame était une robe et un masque, sa Bête était des peaux cousues, et sa Boule de Feu était du coton suspendu au plafond. ''J''ai trompé tout le monde si longtemps que je pensais qu''on ne me démasquerait jamais.''"}, {"en": "Despite everything, Oz agreed to try to grant their wishes the next day. Dorothy still needed a way home, and Oz promised to think about it, asking them to keep his secret in return for his help.", "fr": "Malgré tout, Oz accepta d''essayer d''exaucer leurs vœux le lendemain. Dorothy avait toujours besoin d''un moyen de rentrer, et Oz promit d''y réfléchir, leur demandant de garder son secret en échange de son aide."}, {"en": "The next morning, Oz removed the Scarecrow''s head, emptied the straw, and filled it with a mixture of bran, pins, and needles. ''Hereafter you will be a great man, for I have given you a lot of bran-new brains.''", "fr": "Le lendemain matin, Oz enleva la tête de l''Épouvantail, vida la paille, et la remplit d''un mélange de son, d''épingles, et d''aiguilles. ''Désormais vous serez un grand homme, car je vous ai donné une bonne dose de cervelle toute neuve.''"}]'::jsonb from b;


with b as (select id from books where title = 'Tome 4 : Le grand imposteur' and series_id = (select id from books where title = 'The Wonderful Wizard of Oz' and is_series = true))
insert into book_pages (book_id, page_number, sentences)
select b.id, 4, '[{"en": "For the Tin Woodman, Oz cut a small hole in his tin chest and placed inside a pretty heart made of silk and stuffed with sawdust, then soldered the metal back together. ''Now you have a heart that any man might be proud of.''", "fr": "Pour l''Homme de Fer-Blanc, Oz coupa un petit trou dans sa poitrine en fer-blanc et y plaça un joli cœur fait de soie et rembourré de sciure, puis ressouda le métal. ''Maintenant vous avez un cœur dont tout homme serait fier.''"}, {"en": "For the Lion, Oz poured a green liquid into a dish and told him to drink it. ''If it were inside of you, it would be courage,'' Oz explained. ''This really cannot be called courage until you have swallowed it.''", "fr": "Pour le Lion, Oz versa un liquide vert dans un plat et lui dit de le boire. ''Si c''était en vous, ce serait du courage,'' expliqua Oz. ''Ça ne peut vraiment s''appeler du courage qu''une fois que vous l''aurez avalé.''"}, {"en": "Each of the three left overjoyed, believing their wish had truly been granted. Alone, Oz smiled to himself: ''It was easy to make the Scarecrow and the Lion and the Woodman happy, because they imagined I could do anything. But it will take more than imagination to carry Dorothy back to Kansas.''", "fr": "Chacun des trois repartit ravi, persuadé que son vœu avait vraiment été exaucé. Seul, Oz se sourit à lui-même : ''C''était facile de rendre heureux l''Épouvantail, le Lion et l''Homme de Fer-Blanc, car ils imaginaient que je pouvais tout faire. Mais il faudra plus que de l''imagination pour ramener Dorothy au Kansas.''"}, {"en": "On the fourth day, Oz sent for Dorothy with a plan: build a hot air balloon, made of silk sewn together and coated with glue, to carry them both across the desert.", "fr": "Le quatrième jour, Oz fit appeler Dorothy avec un plan : construire une montgolfière, faite de soie cousue ensemble et enduite de colle, pour les porter tous les deux au-dessus du désert."}, {"en": "Dorothy helped sew strips of green silk together for three days, and Oz painted the finished bag with glue to make it airtight, then fastened a big clothes basket to the bottom with ropes.", "fr": "Dorothy aida à coudre des bandes de soie verte pendant trois jours, et Oz peignit le sac terminé avec de la colle pour le rendre étanche à l''air, puis attacha un grand panier à linge au fond avec des cordes."}, {"en": "Oz announced to his people he would visit a brother Wizard in the clouds, and that the Scarecrow would rule in his absence. The Tin Woodman lit a fire beneath the balloon to fill it with hot air, and it rose until the basket just touched the ground.", "fr": "Oz annonça à son peuple qu''il allait rendre visite à un frère magicien dans les nuages, et que l''Épouvantail règnerait en son absence. L''Homme de Fer-Blanc alluma un feu sous la montgolfière pour la remplir d''air chaud, et elle s''éleva jusqu''à ce que le panier touche à peine le sol."}]'::jsonb from b;


with b as (select id from books where title = 'Tome 4 : Le grand imposteur' and series_id = (select id from books where title = 'The Wonderful Wizard of Oz' and is_series = true))
insert into book_pages (book_id, page_number, sentences)
select b.id, 5, '[{"en": "Dorothy ran to find Toto, who had run off to bark at a kitten. When she finally reached the balloon, the ropes suddenly snapped, and it rose into the air without her.", "fr": "Dorothy courut retrouver Toto, qui était parti aboyer après un chaton. Quand elle atteignit enfin la montgolfière, les cordes cassèrent soudainement, et elle s''éleva dans les airs sans elle."}, {"en": "''Come back!'' she screamed. ''I want to go, too!'' ''I can''t come back, my dear,'' called Oz from the basket. ''Good-bye!'' And that was the last any of them ever saw of Oz, the Wonderful Wizard.", "fr": "''Reviens !'' cria-t-elle. ''Je veux venir aussi !'' ''Je ne peux pas revenir, ma chère,'' cria Oz depuis le panier. ''Adieu !'' Et ce fut la dernière fois que quiconque revit Oz, le Merveilleux Magicien."}]'::jsonb from b;
